import { Component, OnInit, HostListener } from '@angular/core'
import { NgbActiveModal } from '@ng-bootstrap/ng-bootstrap'
import { ConnectionManagerService } from '../services/connectionManager.service'
import { ManagedHost, HostGroup, HostCredentials } from '../api'

@Component({
    selector: 'host-editor',
    template: require('./hostEditor.component.pug'),
    styles: [require('./hostEditor.component.scss')],
})
export class HostEditorComponent implements OnInit {
    editMode = false
    host: Partial<ManagedHost> = {
        type: 'ssh',
        port: 22,
        groupId: null,
    }
    groups: HostGroup[] = []
    credentials: HostCredentials = { authType: 'none' }
    vaultEnabled = false
    showPassword = false
    showPassphrase = false

    readonly connectionTypes = [
        { id: 'ssh', label: 'SSH', defaultPort: 22 },
        { id: 'telnet', label: 'Telnet', defaultPort: 23 },
        { id: 'serial', label: 'Serial', defaultPort: 9600 },
    ]

    availableTypes = this.connectionTypes

    constructor (
        public activeModal: NgbActiveModal,
        private manager: ConnectionManagerService,
    ) { }

    async ngOnInit (): Promise<void> {
        this.groups = this.manager.getGroups()
        const installedTypes = this.manager.getAvailableProviders().map(p => p.id)
        this.availableTypes = this.connectionTypes.filter(t => installedTypes.includes(t.id))
        this.vaultEnabled = this.manager.isVaultEnabled()

        if (this.editMode && this.host.id) {
            const creds = await this.manager.getCredentials(this.host.id)
            if (creds) {
                this.credentials = creds
            }
        }
    }

    onTypeChange (): void {
        const t = this.availableTypes.find(t => t.id === this.host.type)
        if (t && !this.host.port) {
            this.host.port = t.defaultPort
        }
        if (this.host.type !== 'ssh') {
            this.credentials.authType = 'none'
        }
    }

    get portLabel (): string {
        return this.host.type === 'serial' ? 'Baud rate' : 'Port'
    }

    get hostLabel (): string {
        return this.host.type === 'serial' ? 'Serial port (e.g. COM3)' : 'Hostname / IP'
    }

    get isValid (): boolean {
        return !!(this.host.name && this.host.type && this.host.host)
    }

    onPrivateKeyFileChange (event: Event): void {
        const input = event.target as HTMLInputElement
        if (!input.files?.length) return
        const reader = new FileReader()
        reader.onload = () => {
            this.credentials.privateKey = reader.result as string
        }
        reader.readAsText(input.files[0])
    }

    parseTags (value: string): void {
        this.host.tags = value.split(',').map(t => t.trim()).filter(t => t)
    }

    async save (): Promise<void> {
        if (!this.isValid) return

        const hasCredentials = this.vaultEnabled && this.credentials.authType !== 'none'

        if (this.editMode && this.host.id) {
            this.manager.updateHost(this.host.id, { ...this.host as ManagedHost, hasCredentials })
            if (this.vaultEnabled) {
                await this.manager.saveCredentials(this.host.id, this.credentials)
            }
        } else {
            const newHost = this.manager.addHost({ ...this.host as Omit<ManagedHost, 'id'>, hasCredentials })
            if (this.vaultEnabled) {
                await this.manager.saveCredentials(newHost.id, this.credentials)
            }
        }
        this.activeModal.close()
    }

    cancel (): void {
        this.activeModal.dismiss()
    }

    @HostListener('keydown.escape')
    onEscape (): void {
        this.cancel()
    }
}
