import { Component, OnInit, Injector, ViewChild, ElementRef, NgZone, HostListener } from '@angular/core'
import { NgbModal } from '@ng-bootstrap/ng-bootstrap'
import { AppService, BaseTabComponent } from 'tabby-core'
import { ConnectionManagerService } from '../services/connectionManager.service'
import { HostGroup, ManagedHost } from '../api'
import { HostEditorComponent } from './hostEditor.component'
import { GroupEditorComponent } from './groupEditor.component'
import { MultiExecTabComponent } from './multiExecTab.component'

@Component({
    selector: 'connection-panel',
    template: require('./connectionPanel.component.pug'),
    styles: [require('./connectionPanel.component.scss')],
})
export class ConnectionPanelComponent extends BaseTabComponent implements OnInit {
    @ViewChild('searchInput') searchInput: ElementRef<HTMLInputElement>
    @ViewChild('multiExecInput') multiExecInput: ElementRef<HTMLInputElement>

    searchQuery = ''
    groups: HostGroup[] = []
    hosts: ManagedHost[] = []
    viewMode: 'grid' | 'list' = 'grid'
    selectedGroup: HostGroup | null = null

    // ─── Keyboard nav ──────────────────────────────────────────────────────────
    selectedSearchIndex = -1

    // ─── Search suggestions ────────────────────────────────────────────────────
    readonly searchSuggestions: { label: string; hint: string; icon: string; section: string }[] = [
        { label: 'type:ssh',    hint: 'SSH connections',    icon: 'fas fa-terminal',       section: 'Filters' },
        { label: 'type:telnet', hint: 'Telnet connections', icon: 'fas fa-network-wired',  section: 'Filters' },
        { label: 'type:serial', hint: 'Serial connections', icon: 'fas fa-plug',           section: 'Filters' },
        { label: 'name:',       hint: 'Filter by name',     icon: 'fas fa-id-badge',       section: 'Filters' },
        { label: 'user:',       hint: 'Filter by username', icon: 'fas fa-user',           section: 'Filters' },
        { label: 'tag:',        hint: 'Filter by tag',      icon: 'fas fa-tag',            section: 'Filters' },
        { label: 'group:',      hint: 'Filter by group',    icon: 'fas fa-folder',         section: 'Filters' },
        { label: '&&',          hint: 'Match ALL terms',    icon: 'fas fa-check-double',   section: 'Operators' },
        { label: '||',          hint: 'Match ANY term',     icon: 'fas fa-code-branch',    section: 'Operators' },
    ]
    showSuggestions = false
    suggestionIndex = 0

    // ─── Sort ──────────────────────────────────────────────────────────────────
    sortMode: 'default' | 'name' | 'lastConnected' = 'lastConnected'

    // ─── Connection status ─────────────────────────────────────────────────────
    hostStatuses: Record<string, 'online' | 'offline' | 'checking' | 'unknown'> = {}
    isCheckingStatus = false

    // ─── Selection mode ────────────────────────────────────────────────────────
    selectionMode = false
    selectedHostIds = new Set<string>()

    // ─── MultiExec ─────────────────────────────────────────────────────────────
    multiExecMode = false
    multiExecCommand = ''
    multiExecTargetIds = new Set<string>()

    // ─── Drag & drop ───────────────────────────────────────────────────────────
    draggedHost: ManagedHost | null = null
    dragOverHostId: string | null = null
    dragOverGroupId: string | null = null

    constructor (
        injector: Injector,
        public manager: ConnectionManagerService,
        private ngbModal: NgbModal,
        private zone: NgZone,
        private app: AppService,
    ) {
        super(injector)
        this.title = 'Tabby Home'
        this.icon = 'fas fa-server'
    }

    ngOnInit (): void {
        this.refresh()
        this.focused$.subscribe(() => {
            setTimeout(() => {
                if (document.querySelector('.modal.show')) return
                this.searchInput?.nativeElement?.focus()
            }, 50)
        })
    }

    refresh (): void {
        this.groups = this.manager.getGroups()
        this.hosts = this.manager.getHosts()
        if (this.selectedGroup) {
            this.selectedGroup = this.groups.find(g => g.id === this.selectedGroup!.id) ?? null
        }
    }

    // ─── Navigation ────────────────────────────────────────────────────────────

    openGroup (group: HostGroup): void {
        this.selectedGroup = group
        this.searchQuery = ''
        this.selectedSearchIndex = -1
        this.selectionMode = false
        this.selectedHostIds.clear()
    }

    backToRoot (): void {
        this.selectedGroup = null
        this.searchQuery = ''
        this.selectedSearchIndex = -1
        this.selectionMode = false
        this.selectedHostIds.clear()
    }

    @HostListener('keydown', ['$event'])
    onKeyDown (event: KeyboardEvent): void {
        if (event.key === 'Backspace' && this.selectedGroup && !this.searchQuery) {
            const active = document.activeElement as HTMLElement
            if (active?.tagName === 'INPUT' || active?.tagName === 'TEXTAREA') return
            event.preventDefault()
            this.backToRoot()
        }
    }

    @HostListener('mouseup', ['$event'])
    onMouseUp (event: MouseEvent): void {
        if (event.button === 3 && this.selectedGroup) {
            event.preventDefault()
            this.backToRoot()
        }
    }

    // ─── Search keyboard nav ───────────────────────────────────────────────────

    onSearchKeyDown (event: KeyboardEvent): void {
        if (this.showSuggestions) {
            if (event.key === 'ArrowDown') {
                event.preventDefault()
                this.suggestionIndex = (this.suggestionIndex + 1) % this.searchSuggestions.length
                return
            }
            if (event.key === 'ArrowUp') {
                event.preventDefault()
                this.suggestionIndex = (this.suggestionIndex - 1 + this.searchSuggestions.length) % this.searchSuggestions.length
                return
            }
            if (event.key === 'Enter' || event.key === 'Tab') {
                event.preventDefault()
                this.applySuggestion(this.searchSuggestions[this.suggestionIndex])
                return
            }
            if (event.key === 'Escape') {
                event.preventDefault()
                this.showSuggestions = false
                return
            }
        }

        if (!this.searchQuery) return
        const results = this.searchResults
        if (event.key === 'ArrowDown') {
            event.preventDefault()
            this.selectedSearchIndex = Math.min(this.selectedSearchIndex + 1, results.length - 1)
        } else if (event.key === 'ArrowUp') {
            event.preventDefault()
            this.selectedSearchIndex = Math.max(this.selectedSearchIndex - 1, 0)
        } else if (event.key === 'Enter') {
            event.preventDefault()
            const idx = this.selectedSearchIndex >= 0 ? this.selectedSearchIndex : 0
            const host = results[idx]
            if (host) this.connect(host)
        } else if (!['Shift', 'Tab'].includes(event.key)) {
            this.selectedSearchIndex = -1
        }
    }

    onSearchInput (): void {
        if (this.searchQuery.endsWith('/')) {
            this.showSuggestions = true
            this.suggestionIndex = 0
        } else {
            this.showSuggestions = false
        }
    }

    onSearchBlur (): void {
        setTimeout(() => { this.showSuggestions = false }, 150)
    }

    applySuggestion (s: { label: string; hint: string; icon: string; section: string }): void {
        this.searchQuery = this.searchQuery.slice(0, -1) + s.label
        this.showSuggestions = false
        this.suggestionIndex = 0
        setTimeout(() => this.searchInput?.nativeElement?.focus(), 0)
    }

    selectSearchResult (index: number): void {
        this.selectedSearchIndex = index
    }

    clearSearch (): void {
        this.searchQuery = ''
        this.selectedSearchIndex = -1
    }

    // ─── Sort ──────────────────────────────────────────────────────────────────

    cycleSortMode (): void {
        const modes: Array<'default' | 'name' | 'lastConnected'> = ['default', 'name', 'lastConnected']
        const idx = modes.indexOf(this.sortMode)
        this.sortMode = modes[(idx + 1) % modes.length]
    }

    get sortLabel (): string {
        switch (this.sortMode) {
            case 'name': return 'Sort: Name'
            case 'lastConnected': return 'Sort: Recent first'
            default: return 'Sort: Default'
        }
    }

    get sortIcon (): string {
        switch (this.sortMode) {
            case 'name': return 'fas fa-sort-alpha-down'
            case 'lastConnected': return 'fas fa-clock'
            default: return 'fas fa-sort'
        }
    }

    private sortHosts (hosts: ManagedHost[]): ManagedHost[] {
        if (this.sortMode === 'name') {
            return [...hosts].sort((a, b) => a.name.localeCompare(b.name))
        }
        if (this.sortMode === 'lastConnected') {
            return [...hosts].sort((a, b) => (b.lastConnected ?? 0) - (a.lastConnected ?? 0))
        }
        return hosts
    }

    // ─── Filtered + sorted data ────────────────────────────────────────────────

    get visibleGroups (): HostGroup[] {
        if (!this.searchQuery) return this.groups
        return this.groups.filter(g =>
            g.name.toLowerCase().includes(this.searchQuery.toLowerCase()) ||
            this.hostsInGroup(g.id).length > 0
        )
    }

    getHostGroup (host: ManagedHost): HostGroup | null {
        if (!host.groupId) return null
        return this.groups.find(g => g.id === host.groupId) ?? null
    }

    openGroupFromSearch (host: ManagedHost, event: Event): void {
        event.stopPropagation()
        const group = this.getHostGroup(host)
        if (group) {
            this.searchQuery = ''
            this.selectedSearchIndex = -1
            this.selectedGroup = group
        }
    }

    get searchResults (): ManagedHost[] {
        if (!this.searchQuery) return []
        const pool = this.selectedGroup
            ? this.hosts.filter(h => h.groupId === this.selectedGroup!.id)
            : this.hosts
        return pool.filter(h => this.matchesSearch(h))
    }

    get recentHosts (): ManagedHost[] {
        return this.hosts
            .filter(h => h.lastConnected)
            .sort((a, b) => (b.lastConnected ?? 0) - (a.lastConnected ?? 0))
            .slice(0, 10)
    }

    get rootHosts (): ManagedHost[] {
        const groupIds = new Set(this.groups.map(g => g.id))
        return this.sortHosts(
            this.hosts.filter(h => {
                const gid = h.groupId
                return (gid == null || gid === 'null' || gid === '' || !groupIds.has(gid)) && this.matchesSearch(h)
            })
        )
    }

    get groupHosts (): ManagedHost[] {
        if (!this.selectedGroup) return []
        return this.sortHosts(this.hostsInGroup(this.selectedGroup.id))
    }

    hostsInGroup (groupId: string): ManagedHost[] {
        return this.hosts.filter(h => h.groupId === groupId && this.matchesSearch(h))
    }

    hostCountInGroup (groupId: string): number {
        return this.hosts.filter(h => h.groupId === groupId).length
    }

    private matchesSearch (host: ManagedHost): boolean {
        if (!this.searchQuery) return true
        const groupName = this.groups.find(g => g.id === host.groupId)?.name ?? ''

        const matchToken = (token: string): boolean => {
            const t = token.trim()
            if (!t) return true

            const colonIdx = t.indexOf(':')
            if (colonIdx > 0) {
                const prefix = t.slice(0, colonIdx)
                const val = t.slice(colonIdx + 1)
                switch (prefix) {
                    case 'type':
                        return (host.type ?? '').toLowerCase() === val
                    case 'name':
                        return host.name.toLowerCase().includes(val)
                    case 'user':
                        return (host.username ?? '').toLowerCase().includes(val)
                    case 'tag':
                        return (host.tags ?? []).some(tag => tag.toLowerCase().includes(val))
                    case 'group':
                        return groupName.toLowerCase().includes(val)
                }
            }

            return (
                host.name.toLowerCase().includes(t) ||
                (host.host ?? '').toLowerCase().includes(t) ||
                (host.username ?? '').toLowerCase().includes(t) ||
                (host.tags ?? []).some(tag => tag.toLowerCase().includes(t)) ||
                (host.notes ?? '').toLowerCase().includes(t) ||
                groupName.toLowerCase().includes(t)
            )
        }

        const q = this.searchQuery.toLowerCase()
        if (q.includes('||')) {
            return q.split('||').some(token => matchToken(token))
        }
        if (q.includes('&&')) {
            return q.split('&&').every(token => matchToken(token))
        }
        return matchToken(q)
    }

    // ─── Connection status ─────────────────────────────────────────────────────

    async checkAllStatuses (): Promise<void> {
        if (this.isCheckingStatus) return
        this.isCheckingStatus = true
        const hostsToCheck = this.hosts.filter(h => h.host && h.type !== 'serial')
        const initial: Record<string, 'checking'> = {}
        for (const h of hostsToCheck) initial[h.id] = 'checking'
        this.hostStatuses = { ...this.hostStatuses, ...initial }

        await Promise.all(hostsToCheck.map(async host => {
            const status = await this.manager.checkHostStatus(host)
            this.zone.run(() => {
                this.hostStatuses = { ...this.hostStatuses, [host.id]: status }
            })
        }))
        this.zone.run(() => { this.isCheckingStatus = false })
    }

    getHostStatus (host: ManagedHost): string {
        return this.hostStatuses[host.id] ?? 'unknown'
    }

    // ─── Drag & drop ───────────────────────────────────────────────────────────

    onDragStart (host: ManagedHost, event: DragEvent): void {
        this.draggedHost = host
        event.dataTransfer?.setData('text/plain', host.id)
    }

    onDragEnd (event?: DragEvent): void {
        const host = this.draggedHost
        this.draggedHost = null
        this.dragOverHostId = null
        this.dragOverGroupId = null

        if (!host || !event) return
        const target = document.elementFromPoint(event.clientX, event.clientY) as HTMLElement | null
        if (!target) return
        const tabHeader = target.closest('tab-header')
        if (!tabHeader) return
        const nameEl = tabHeader.querySelector('.cdk-drag.name')
        if (!nameEl) return
        const tabTitle = nameEl.textContent?.trim()
        const instance = MultiExecTabComponent.instances.find(i => i.title === tabTitle)
        if (!instance) return
        this.zone.run(() => instance.addHost(host))
    }

    onDragOverHost (event: DragEvent, hostId: string): void {
        if (!this.draggedHost) return
        event.preventDefault()
        this.dragOverHostId = hostId
        this.dragOverGroupId = null
    }

    onDropOnHost (targetHost: ManagedHost): void {
        if (!this.draggedHost || this.draggedHost.id === targetHost.id) {
            this.onDragEnd()
            return
        }
        if (this.draggedHost.groupId === targetHost.groupId) {
            // Same group: reorder
            this.manager.reorderHost(this.draggedHost.id, targetHost.id)
        } else {
            // Different group: move to target's group
            this.manager.updateHost(this.draggedHost.id, { groupId: targetHost.groupId })
        }
        this.onDragEnd()
        this.refresh()
    }

    onDragOverGroup (event: DragEvent, groupId: string): void {
        if (!this.draggedHost) return
        event.preventDefault()
        this.dragOverGroupId = groupId
        this.dragOverHostId = null
    }

    onDropOnGroup (group: HostGroup): void {
        if (!this.draggedHost) return
        this.manager.updateHost(this.draggedHost.id, { groupId: group.id })
        this.onDragEnd()
        this.refresh()
    }

    onDragLeave (): void {
        this.dragOverHostId = null
        this.dragOverGroupId = null
    }

    // ─── Host actions ──────────────────────────────────────────────────────────

    async connect (host: ManagedHost): Promise<void> {
        await this.manager.connect(host)
    }

    async connectAllInGroup (group: HostGroup, event: Event): Promise<void> {
        event.stopPropagation()
        const hosts = this.hosts.filter(h => h.groupId === group.id)
        for (const host of hosts) await this.manager.connect(host)
    }

    async connectAllInGroupSplit (group: HostGroup, event: Event): Promise<void> {
        event.stopPropagation()
        const hosts = this.hosts.filter(h => h.groupId === group.id)
        await this.manager.connectAllSplit(hosts)
    }


    async connectGroupHosts (): Promise<void> {
        for (const host of this.currentViewHosts) await this.manager.connect(host)
    }

    async connectGroupHostsSplit (): Promise<void> {
        await this.manager.connectAllSplit(this.currentViewHosts)
    }

    // ─── Selection mode ────────────────────────────────────────────────────────

    toggleSelectionMode (): void {
        this.selectionMode = !this.selectionMode
        this.selectedHostIds.clear()
    }

    toggleHostSelection (host: ManagedHost, event: Event): void {
        event.stopPropagation()
        if (this.selectedHostIds.has(host.id)) {
            this.selectedHostIds.delete(host.id)
        } else {
            this.selectedHostIds.add(host.id)
        }
    }

    isHostSelected (host: ManagedHost): boolean {
        return this.selectedHostIds.has(host.id)
    }

    private get currentViewHosts (): ManagedHost[] {
        return this.selectedGroup ? this.groupHosts : this.rootHosts
    }

    selectAll (): void {
        this.currentViewHosts.forEach(h => this.selectedHostIds.add(h.id))
    }

    deselectAll (): void {
        this.selectedHostIds.clear()
    }

    get selectedHosts (): ManagedHost[] {
        return this.currentViewHosts.filter(h => this.selectedHostIds.has(h.id))
    }

    async connectSelected (): Promise<void> {
        for (const host of this.selectedHosts) await this.manager.connect(host)
        this.toggleSelectionMode()
    }

    async splitSelected (): Promise<void> {
        await this.manager.connectAllSplit(this.selectedHosts)
        this.toggleSelectionMode()
    }

    openMultiExecView (hosts: ManagedHost[]): void {
        if (hosts.length === 0) return
        this.selectionMode = false
        this.selectedHostIds.clear()
        this.multiExecMode = false
        this.multiExecTargetIds.clear()
        this.app.openNewTab({ type: MultiExecTabComponent, inputs: { hosts } })
    }

    // ─── MultiExec ─────────────────────────────────────────────────────────────

    get connectedHosts (): ManagedHost[] {
        const ids = this.manager.connectedTabs
        return this.hosts.filter(h => ids.has(h.id))
    }

    get multiExecTargetHosts (): ManagedHost[] {
        return this.connectedHosts.filter(h => this.multiExecTargetIds.has(h.id))
    }

    toggleMultiExecMode (): void {
        this.multiExecMode = !this.multiExecMode
        if (this.multiExecMode) {
            this.connectedHosts.forEach(h => this.multiExecTargetIds.add(h.id))
            setTimeout(() => this.multiExecInput?.nativeElement?.focus(), 80)
        } else {
            this.multiExecTargetIds.clear()
            this.multiExecCommand = ''
        }
    }

    isMultiExecTarget (host: ManagedHost): boolean {
        return this.multiExecTargetIds.has(host.id)
    }

    toggleMultiExecTarget (host: ManagedHost, event: Event): void {
        event.stopPropagation()
        if (this.multiExecTargetIds.has(host.id)) {
            this.multiExecTargetIds.delete(host.id)
        } else {
            this.multiExecTargetIds.add(host.id)
        }
    }

    selectAllConnected (): void {
        this.connectedHosts.forEach(h => this.multiExecTargetIds.add(h.id))
    }

    deselectAllConnected (): void {
        this.multiExecTargetIds.clear()
    }

    sendMultiExec (): void {
        if (!this.multiExecCommand.trim() || this.multiExecTargetIds.size === 0) return
        this.manager.sendMultiExec(this.multiExecCommand, [...this.multiExecTargetIds])
        this.multiExecCommand = ''
        setTimeout(() => this.multiExecInput?.nativeElement?.focus(), 30)
    }

    onMultiExecKeyDown (event: KeyboardEvent): void {
        if (event.ctrlKey || event.altKey || event.metaKey) {
            this.multiExecInput?.nativeElement?.blur()
            return
        }
        if (event.key === 'Enter') {
            event.preventDefault()
            this.sendMultiExec()
        }
    }

    async addHost (groupId?: string): Promise<void> {
        const modal = this.ngbModal.open(HostEditorComponent, { size: 'lg' })
        modal.componentInstance.host = { type: 'ssh', port: 22, groupId: groupId ?? null }
        try {
            await modal.result
            this.refresh()
        } catch { /* dismissed */ }
    }

    async editHost (host: ManagedHost, event: Event): Promise<void> {
        event.stopPropagation()
        const wasInGroup = !!this.selectedGroup
        const modal = this.ngbModal.open(HostEditorComponent, { size: 'lg' })
        modal.componentInstance.host = { ...host }
        modal.componentInstance.editMode = true
        try {
            await modal.result
            this.refresh()
            if (wasInGroup) {
                this.backToRoot()
            }
        } catch { /* dismissed */ }
    }

    duplicateHost (host: ManagedHost, event: Event): void {
        event.stopPropagation()
        this.manager.duplicateHost(host.id)
        this.refresh()
    }

    async deleteHost (host: ManagedHost, event: Event): Promise<void> {
        event.stopPropagation()
        if (confirm(`Delete "${host.name}"?`)) {
            await this.manager.deleteHost(host.id)
            this.refresh()
        }
    }

    // ─── Group actions ─────────────────────────────────────────────────────────

    async addGroup (): Promise<void> {
        const modal = this.ngbModal.open(GroupEditorComponent)
        try {
            await modal.result
            this.refresh()
        } catch { /* dismissed */ }
    }

    async editGroup (group: HostGroup, event: Event): Promise<void> {
        event.stopPropagation()
        const modal = this.ngbModal.open(GroupEditorComponent)
        modal.componentInstance.group = { ...group }
        modal.componentInstance.editMode = true
        try {
            await modal.result
            this.refresh()
        } catch { /* dismissed */ }
    }

    deleteGroup (group: HostGroup, event: Event): void {
        event.stopPropagation()
        if (confirm(`Delete group "${group.name}"?\nHosts will be moved to root.`)) {
            this.manager.deleteGroup(group.id)
            if (this.selectedGroup?.id === group.id) {
                this.selectedGroup = null
            }
            this.refresh()
        }
    }

    // ─── Import / Export ───────────────────────────────────────────────────────

    exportConnections (): void {
        const json = this.manager.exportData()
        const blob = new Blob([json], { type: 'application/json' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `connections-${new Date().toISOString().slice(0, 10)}.json`
        a.click()
        URL.revokeObjectURL(url)
    }

    triggerImport (): void {
        document.getElementById('cm-import-file')?.click()
    }

    importConnections (event: Event): void {
        const input = event.target as HTMLInputElement
        const file = input.files?.[0]
        if (!file) return
        const reader = new FileReader()
        reader.onload = () => {
            try {
                const result = this.manager.importData(reader.result as string)
                this.refresh()
                alert(`Imported: ${result.groupsAdded} groups, ${result.hostsAdded} hosts`)
            } catch {
                alert('Import failed: invalid file format')
            }
        }
        reader.readAsText(file)
        input.value = ''
    }

    // ─── Helpers ───────────────────────────────────────────────────────────────

    getHostIcon (host: ManagedHost): string {
        switch (host.type) {
            case 'ssh': return 'fas fa-terminal'
            case 'telnet': return 'fas fa-network-wired'
            case 'serial': return 'fas fa-plug'
            default: return 'fas fa-server'
        }
    }

    getHostIconColor (_host: ManagedHost): string {
        return '#ffffff'
    }

    getHostIconBg (host: ManagedHost): string {
        switch (host.type) {
            case 'ssh': return '#88c0d0'
            case 'telnet': return '#d08770'
            case 'serial': return '#b48ead'
            default: return '#81a1c1'
        }
    }

    getHostDescription (host: ManagedHost): string {
        const parts = [host.type]
        if (host.host) parts.push(host.host)
        if (host.username) parts.push(host.username)
        return parts.join(', ')
    }
}
