import { Injectable, Inject } from '@angular/core'
import { ConfigService, ProfilesService, ProfileProvider, Profile, PartialProfile, VaultService, AppService, TabsService, SplitTabComponent, BaseTabComponent } from 'tabby-core'
import { v4 as uuidv4 } from 'uuid'
import { HostGroup, ManagedHost, HostCredentials } from '../api'

const VAULT_TYPE = 'connection-manager:credentials'

@Injectable({ providedIn: 'root' })
export class ConnectionManagerService {

    readonly connectedTabs = new Map<string, BaseTabComponent>()
    private credentialsCache = new Map<string, HostCredentials>()
    private cacheReady = false

    constructor (
        private config: ConfigService,
        private profilesService: ProfilesService,
        private vault: VaultService,
        private app: AppService,
        private tabsService: TabsService,
        @Inject(ProfileProvider) private profileProviders: ProfileProvider<Profile>[],
    ) { }

    // ─── Groups ────────────────────────────────────────────────────────────────

    getGroups (): HostGroup[] {
        return this.config.store.connectionManager?.groups ?? []
    }

    addGroup (name: string, color?: string, parentId?: string | null): HostGroup {
        const group: HostGroup = {
            id: uuidv4(),
            name,
            color,
            expanded: true,
            parentId: parentId ?? null,
        }
        this.config.store.connectionManager.groups.push(group)
        this.config.save()
        return group
    }

    updateGroup (id: string, changes: Partial<HostGroup>): void {
        const groups: HostGroup[] = this.config.store.connectionManager.groups
        const idx = groups.findIndex(g => g.id === id)
        if (idx !== -1) {
            groups[idx] = { ...groups[idx], ...changes }
            this.config.save()
        }
    }

    deleteGroup (id: string): void {
        const hosts: ManagedHost[] = this.config.store.connectionManager.hosts
        hosts.forEach(h => {
            if (h.groupId === id) {
                h.groupId = null
            }
        })
        this.config.store.connectionManager.groups =
            this.config.store.connectionManager.groups.filter((g: HostGroup) => g.id !== id)
        this.config.save()
    }

    toggleGroupExpanded (id: string): void {
        const groups: HostGroup[] = this.config.store.connectionManager.groups
        const group = groups.find(g => g.id === id)
        if (group) {
            group.expanded = !group.expanded
            this.config.save()
        }
    }

    // ─── Hosts ─────────────────────────────────────────────────────────────────

    getHosts (): ManagedHost[] {
        return this.config.store.connectionManager?.hosts ?? []
    }

    addHost (host: Omit<ManagedHost, 'id'>): ManagedHost {
        const newHost: ManagedHost = { ...host, id: uuidv4() }
        this.config.store.connectionManager.hosts.push(newHost)
        this.config.save()
        return newHost
    }

    updateHost (id: string, changes: Partial<ManagedHost>): void {
        const hosts: ManagedHost[] = this.config.store.connectionManager.hosts
        const idx = hosts.findIndex(h => h.id === id)
        if (idx !== -1) {
            hosts[idx] = { ...hosts[idx], ...changes }
            this.config.save()
        }
    }

    async deleteHost (id: string): Promise<void> {
        this.config.store.connectionManager.hosts =
            this.config.store.connectionManager.hosts.filter((h: ManagedHost) => h.id !== id)
        this.config.save()
        await this.deleteCredentials(id)
    }

    duplicateHost (id: string): ManagedHost | null {
        const hosts: ManagedHost[] = this.config.store.connectionManager.hosts
        const original = hosts.find(h => h.id === id)
        if (!original) return null
        const copy: ManagedHost = {
            ...original,
            id: uuidv4(),
            name: `${original.name} (copy)`,
            lastConnected: undefined,
            hasCredentials: false,
        }
        this.config.store.connectionManager.hosts.push(copy)
        this.config.save()
        return copy
    }

    reorderHost (draggedId: string, targetId: string): void {
        const hosts: ManagedHost[] = this.config.store.connectionManager.hosts
        const draggedIdx = hosts.findIndex(h => h.id === draggedId)
        const targetIdx = hosts.findIndex(h => h.id === targetId)
        if (draggedIdx === -1 || targetIdx === -1 || draggedIdx === targetIdx) return
        const [dragged] = hosts.splice(draggedIdx, 1)
        const newIdx = hosts.findIndex(h => h.id === targetId)
        hosts.splice(newIdx, 0, dragged)
        this.config.save()
    }

    // ─── Import / Export ───────────────────────────────────────────────────────

    exportData (): string {
        return JSON.stringify({
            version: 1,
            exportedAt: new Date().toISOString(),
            groups: this.getGroups(),
            hosts: this.getHosts(),
        }, null, 2)
    }

    importData (json: string): { groupsAdded: number, hostsAdded: number } {
        const data = JSON.parse(json)
        const groups: HostGroup[] = data.groups ?? []
        const hosts: ManagedHost[] = data.hosts ?? []
        const groupIdMap = new Map<string, string>()
        for (const g of groups) {
            const newId = uuidv4()
            groupIdMap.set(g.id, newId)
            this.config.store.connectionManager.groups.push({ ...g, id: newId })
        }
        for (const h of hosts) {
            const newGroupId = h.groupId ? (groupIdMap.get(h.groupId) ?? null) : null
            this.config.store.connectionManager.hosts.push({
                ...h,
                id: uuidv4(),
                groupId: newGroupId,
                lastConnected: undefined,
                hasCredentials: false,
            })
        }
        this.config.save()
        return { groupsAdded: groups.length, hostsAdded: hosts.length }
    }

    // ─── Connection status ─────────────────────────────────────────────────────

    async checkHostStatus (host: ManagedHost): Promise<'online' | 'offline' | 'unknown'> {
        if (!host.host || host.type === 'serial') return 'unknown'
        try {
            // eslint-disable-next-line @typescript-eslint/no-require-imports
            const net = require('net')
            const port = host.port ?? (host.type === 'ssh' ? 22 : 23)
            return await new Promise<'online' | 'offline'>(resolve => {
                const socket = new net.Socket()
                const timer = setTimeout(() => { socket.destroy(); resolve('offline') }, 3000)
                socket.on('connect', () => { clearTimeout(timer); socket.destroy(); resolve('online') })
                socket.on('error', () => { clearTimeout(timer); socket.destroy(); resolve('offline') })
                socket.connect(port, host.host)
            })
        } catch {
            return 'unknown'
        }
    }

    // ─── Credentials (Vault) ───────────────────────────────────────────────────

    isVaultEnabled (): boolean {
        return this.vault.isEnabled()
    }

    private async ensureCache (): Promise<void> {
        if (this.cacheReady) return
        if (!this.vault.isEnabled()) return
        const vault = await this.vault.load()
        if (!vault) return
        for (const secret of vault.secrets.filter(s => s.type === VAULT_TYPE)) {
            try {
                this.credentialsCache.set(secret.key['hostId'], JSON.parse(secret.value))
            } catch { /* skip invalid */ }
        }
        this.cacheReady = true
    }

    async saveCredentials (hostId: string, creds: HostCredentials): Promise<void> {
        if (!this.vault.isEnabled()) return
        await this.ensureCache()
        await this.vault.addSecret({
            type: VAULT_TYPE,
            key: { hostId },
            value: JSON.stringify(creds),
        })
        this.credentialsCache.set(hostId, creds)
    }

    async getCredentials (hostId: string): Promise<HostCredentials | null> {
        if (!this.vault.isEnabled()) return null
        await this.ensureCache()
        return this.credentialsCache.get(hostId) ?? null
    }

    async deleteCredentials (hostId: string): Promise<void> {
        if (!this.vault.isEnabled()) return
        await this.vault.removeSecret(VAULT_TYPE, { hostId })
        this.credentialsCache.delete(hostId)
    }

    // ─── Connect ───────────────────────────────────────────────────────────────

    async connect (host: ManagedHost): Promise<BaseTabComponent | null> {
        const profile = await this.buildProfile(host)
        if (!profile) return null
        const params = await this.profilesService.newTabParametersForProfile(profile)
        if (!params) return null
        const tab = this.tabsService.create(params)
        this.app.addTabRaw(tab)
        this.app.selectTab(tab)
        this.updateHost(host.id, { lastConnected: Date.now() })
        this.trackTab(host.id, tab)
        return tab
    }

    async connectAllSplit (hosts: ManagedHost[]): Promise<SplitTabComponent | null> {
        if (hosts.length === 0) return null
        if (hosts.length === 1) {
            await this.connect(hosts[0])
            return null
        }

        const splitTab = this.tabsService.create({ type: SplitTabComponent }) as SplitTabComponent
        this.app.addTabRaw(splitTab)
        this.app.selectTab(splitTab)

        let prevTab: BaseTabComponent | null = null
        for (const host of hosts) {
            const profile = await this.buildProfile(host)
            if (!profile) continue
            const params = await this.profilesService.newTabParametersForProfile(profile)
            if (!params) continue
            const tab = this.tabsService.create(params)
            this.updateHost(host.id, { lastConnected: Date.now() })
            await splitTab.addTab(tab, prevTab, 'r')
            this.trackTab(host.id, tab)
            prevTab = tab
        }

        return splitTab
    }

    sendMultiExec (command: string, hostIds: string[]): void {
        const line = command.endsWith('\n') ? command : command + '\r'
        for (const id of hostIds) {
            const tab = this.connectedTabs.get(id)
            if (!tab) continue
            const session = (tab as any).session
            if (!session?.open) continue
            ;(tab as any).sendInput(line)
        }
    }

    sendRaw (data: string, hostIds: string[]): void {
        for (const id of hostIds) {
            const tab = this.connectedTabs.get(id)
            if (!tab) continue
            const session = (tab as any).session
            if (!session?.open) continue
            ;(tab as any).sendInput(data)
        }
    }

    async createTerminalTab (host: ManagedHost): Promise<BaseTabComponent | null> {
        const profile = await this.buildProfile(host)
        if (!profile) return null
        const params = await this.profilesService.newTabParametersForProfile(profile)
        if (!params) return null
        const tab = this.tabsService.create(params)
        this.updateHost(host.id, { lastConnected: Date.now() })
        this.trackTab(host.id, tab)
        return tab
    }

    private trackTab (hostId: string, tab: BaseTabComponent): void {
        this.connectedTabs.set(hostId, tab)
        tab.destroyed$.subscribe(() => {
            if (this.connectedTabs.get(hostId) === tab) {
                this.connectedTabs.delete(hostId)
            }
        })
    }

    private async buildProfile (host: ManagedHost): Promise<PartialProfile<Profile> | null> {
        if (host.profileId) {
            const profiles = await this.profilesService.getProfiles()
            const found = profiles.find(p => p.id === host.profileId)
            if (found) return found as PartialProfile<Profile>
        }

        const provider = this.profileProviders.find(p => p.id === host.type)
        if (!provider) {
            console.error(`[ConnectionManager] No provider for type: ${host.type}`)
            return null
        }

        const credentials = await this.getCredentials(host.id)
        return {
            id: `connection-manager:temp:${host.id}`,
            type: host.type,
            name: host.name,
            group: '',
            options: this.buildProfileOptions(host, credentials),
        }
    }

    getAvailableProviders (): ProfileProvider<Profile>[] {
        return this.profileProviders
    }

    private buildProfileOptions (host: ManagedHost, creds: HostCredentials | null): Record<string, any> {
        if (host.type === 'ssh') {
            const options: Record<string, any> = {
                host: host.host ?? '',
                port: host.port ?? 22,
                user: host.username ?? '',
            }
            if (creds) {
                if (creds.authType === 'password') {
                    options.auth = 'password'
                    options.password = creds.password ?? ''
                } else if (creds.authType === 'privateKey' && creds.privateKey) {
                    options.auth = 'publicKey'
                    options.privateKeys = [creds.privateKey]
                    if (creds.passphrase) {
                        options.passphrase = creds.passphrase
                    }
                }
            }
            return options
        }

        if (host.type === 'telnet') {
            return {
                host: host.host ?? '',
                port: host.port ?? 23,
            }
        }

        if (host.type === 'serial') {
            return {
                port: host.host ?? '',
                baudrate: host.port ?? 9600,
            }
        }

        return {}
    }
}
