import { Component } from '@angular/core'
import { NgbActiveModal } from '@ng-bootstrap/ng-bootstrap'
import { ConnectionManagerService } from '../services/connectionManager.service'
import { HostGroup } from '../api'

@Component({
    selector: 'group-editor',
    template: require('./groupEditor.component.pug'),
})
export class GroupEditorComponent {
    editMode = false
    group: Partial<HostGroup> = {
        name: '',
        color: '',
    }

    readonly colorPresets = [
        '#e74c3c', '#e67e22', '#f1c40f',
        '#2ecc71', '#1abc9c', '#3498db',
        '#9b59b6', '#e91e63', '#607d8b',
    ]

    constructor (
        public activeModal: NgbActiveModal,
        private manager: ConnectionManagerService,
    ) { }

    get isValid (): boolean {
        return !!this.group.name?.trim()
    }

    save (): void {
        if (!this.isValid) return
        if (this.editMode && this.group.id) {
            this.manager.updateGroup(this.group.id, this.group)
        } else {
            this.manager.addGroup(this.group.name!, this.group.color)
        }
        this.activeModal.close()
    }

    cancel (): void {
        this.activeModal.dismiss()
    }
}
