import { Injectable } from '@angular/core'
import { ToolbarButtonProvider, ToolbarButton, AppService } from 'tabby-core'
import { ConnectionPanelComponent } from './components/connectionPanel.component'

@Injectable()
export class ConnectionManagerToolbarButtonProvider extends ToolbarButtonProvider {
    constructor (private app: AppService) {
        super()
    }

    provide (): ToolbarButton[] {
        return [{
            // SVG icon inline
            icon: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">
                <path d="M4 6h16v2H4zm0 5h16v2H4zm0 5h16v2H4z"/>
                <rect x="2" y="3" width="20" height="18" rx="2" ry="2"
                      fill="none" stroke="currentColor" stroke-width="1.5"/>
            </svg>`,
            title: 'Tabby Home',
            weight: -1,
            click: () => this.openOrFocus(),
        }]
    }

    private openOrFocus (): void {
        // Nếu tab panel đã mở thì focus vào đó
        const existing = this.app.tabs.find(
            t => t instanceof ConnectionPanelComponent
        )
        if (existing) {
            this.app.selectTab(existing)
            return
        }

        this.app.openNewTab({
            type: ConnectionPanelComponent,
            inputs: {},
        })
    }
}
