import { NgModule } from '@angular/core'
import { CommonModule } from '@angular/common'
import { FormsModule } from '@angular/forms'
import { NgbModule } from '@ng-bootstrap/ng-bootstrap'
import TabbyCoreModule, { ConfigProvider, ToolbarButtonProvider, HotkeyProvider, AppService, HotkeysService } from 'tabby-core'

import { ConnectionPanelComponent } from './components/connectionPanel.component'
import { HostEditorComponent } from './components/hostEditor.component'
import { GroupEditorComponent } from './components/groupEditor.component'
import { MultiExecTabComponent } from './components/multiExecTab.component'

import { ConnectionManagerConfigProvider } from './config'
import { ConnectionManagerToolbarButtonProvider } from './toolbar'
import { ConnectionManagerHotkeyProvider } from './hotkey'

/** @hidden */
@NgModule({
    imports: [
        NgbModule,
        CommonModule,
        FormsModule,
        TabbyCoreModule,
    ],
    providers: [
        { provide: ConfigProvider, useClass: ConnectionManagerConfigProvider, multi: true },
        { provide: ToolbarButtonProvider, useClass: ConnectionManagerToolbarButtonProvider, multi: true },
        { provide: HotkeyProvider, useClass: ConnectionManagerHotkeyProvider, multi: true },
    ],
    declarations: [
        ConnectionPanelComponent,
        HostEditorComponent,
        GroupEditorComponent,
        MultiExecTabComponent,
    ],
    entryComponents: [
        ConnectionPanelComponent,
        HostEditorComponent,
        GroupEditorComponent,
        MultiExecTabComponent,
    ],
})
export default class ConnectionManagerModule {
    constructor (app: AppService, hotkeys: HotkeysService) {
        app.ready$.subscribe(() => {
            app.openNewTab({ type: ConnectionPanelComponent, inputs: {} })
        })

        hotkeys.hotkey$.subscribe(hotkey => {
            if (hotkey === 'connection-manager-open') {
                const existing = app.tabs.find(t => t instanceof ConnectionPanelComponent)
                if (existing) {
                    app.selectTab(existing)
                } else {
                    app.openNewTab({ type: ConnectionPanelComponent, inputs: {} })
                }
            }
        })
    }
}

export * from './api'
export { ConnectionManagerService } from './services/connectionManager.service'
